style.css:
/* ═══════════════════════════════════════
   ? APPLE MUSIC — PINK GIRL THEME ?
   ═══════════════════════════════════════ */

/* MAIN BACKGROUND */
body,
html {
    background: #fff0f6 !important;
}

/* Main Apple Music content */
main,
[class*="content"],
[class*="main"] {
    background: #fff0f6 !important;
}

/* SIDEBAR */
nav,
aside,
[class*="sidebar"] {
    background: #ffd6e8 !important;
    border-right: 1px solid #f3a6c5 !important;
}

/* SIDEBAR TEXT */
nav *,
aside *,
[class*="sidebar"] * {
    color: #7a3153 !important;
}

/* SIDEBAR HOVER */
nav a:hover,
aside a:hover,
[class*="sidebar"] a:hover {
    background: #ffb8d3 !important;
    border-radius: 12px !important;
}

/* ACTIVE SIDEBAR ITEM */
nav [aria-current="page"],
aside [aria-current="page"] {
    background: #ff9fc5 !important;
    color: white !important;
    border-radius: 12px !important;
}

/* HEADINGS */
h1,
h2,
h3,
h4 {
    color: #8f3d61 !important;
}

/* GENERAL TEXT */
p,
span {
    color: #70405a;
}

/* LINKS */
a {
    color: #d94f87 !important;
}

/* BUTTONS */
button {
    background: #ff9fc5 !important;
    color: white !important;
    border: none !important;
    border-radius: 999px !important;
    transition: 0.2s ease !important;
}

/* BUTTON HOVER */
button:hover {
    background: #f47eaa !important;
    transform: scale(1.04);
}

/* PLAY BUTTON */
button[aria-label*="Play"],
button[title*="Play"] {
    background: #e85b91 !important;
    color: white !important;
    border-radius: 50% !important;
}

/* ALBUM / PLAYLIST CARDS */
[class*="card"],
[class*="Card"] {
    background: #ffe4ef !important;
    border-radius: 18px !important;
    border: 1px solid #f6b8d0 !important;
}

/* CARD HOVER */
[class*="card"]:hover,
[class*="Card"]:hover {
    background: #ffd2e4 !important;
    box-shadow: 0 8px 25px rgba(220, 90, 140, 0.15) !important;
}

/* ALBUM ART */
img {
    border-radius: 14px !important;
}

/* LARGE ALBUM ART */
[class*="artwork"] img,
[class*="Artwork"] img {
    border-radius: 20px !important;
}

/* SEARCH BAR */
input,
[role="searchbox"] {
    background: #ffe0ec !important;
    border: 1px solid #f2a7c5 !important;
    border-radius: 999px !important;
    color: #743550 !important;
}

input::placeholder {
    color: #c77b9b !important;
}

/* SEARCH BAR FOCUS */
input:focus,
[role="searchbox"]:focus {
    outline: 2px solid #ed8db4 !important;
}

/* MUSIC PLAYER */
footer,
[class*="player"],
[class*="Player"],
[class*="now-playing"] {
    background: #ffc4db !important;
    border-top: 1px solid #ed91b5 !important;
}

/* PLAYER TEXT */
footer *,
[class*="player"] * {
    color: #743550 !important;
}

/* PROGRESS BAR */
input[type="range"] {
    accent-color: #e85b91 !important;
}

/* SCROLLBAR */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #ffeaf2;
}

::-webkit-scrollbar-thumb {
    background: #f29abb;
    border-radius: 999px;
}

::-webkit-scrollbar-thumb:hover {
    background: #e77ba4;
}

/* SELECTION */
::selection {
    background: #f49abd !important;
    color: white !important;
}

/* SUBTLE PINK GLOW */
[class*="card"]:hover img {
    box-shadow: 0 5px 20px rgba(226, 91, 139, 0.25);
}

/* ═══════════════════════════════════════
   ? EXTRA CUTE DETAILS
   ═══════════════════════════════════════ */

/* Make separators pink */
hr {
    border-color: #f2b2cb !important;
}

/* Menus */
[role="menu"],
[role="dialog"] {
    background: #ffe1ed !important;
    border: 1px solid #f2a5c3 !important;
    border-radius: 16px !important;
}

/* Menu items */
[role="menuitem"]:hover {
    background: #ffb9d4 !important;
    border-radius: 10px !important;
}

/* Tooltips */
[role="tooltip"] {
    background: #d9578b !important;
    color: white !important;
    border-radius: 10px !important;
}
